/** The status a claim had at the end of a day (yyyy-mm-dd), as its status log records it (the last
 *  line logged on or before it); null when it had none yet. */
export function statusAt(c: Claim, day: string): ClaimStatus | null {
  let at: ClaimStatus | null = null;
  for (const l of c.log) if (l.date <= day) at = l.status;
  return at;
}

/** Whether a claim is open: OPEN or PENDING. Only an open claim goes overdue. */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Whether a claim is deferred on the sheet's today: open, and its deferral date not yet reached. */
/** Whether a REVIEW claim is late for review on the sheet's today: its review day plus the review SLA
 *  (whole days; blank: none) is before today. */
export function reviewLate(c: Claim, today: string | null, sla: string): boolean {
  return c.status === 'REVIEW' && c.reviewOn !== null && today !== null && sla !== ''
    && plusDays(c.reviewOn, Number(sla)) < today;
}

export function deferred(c: Claim, today: string | null): boolean {
  return isOpen(c) && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
}

/** The refusal of a change to a claim dated inside a closed period. */
const CLOSED = 'That date is inside a closed period.';

/** The refusal of editing a claim another user's open editor locks (or no longer a DRAFT). */
const LOCKED = 'Another user is editing this claim, or it is no longer a DRAFT.';

/** The refusal of a correction that names no SETTLED claim of its person. */
const UNCORRECTABLE = 'A negative amount must correct a SETTLED claim of this person, by its number.';

const PAST: Record<ClaimAction, string> = {
  open: 'opened',
  review: 'reviewed',
  settle: 'settled',
  resettle: 're-settled',
  approve: 'approved',
-- A claim a clerk settles above the clerk limit goes to PENDING until a steward approves it
-- (SETTLED) or rejects it (back to OPEN). The status's allowed values gain PENDING, so the status
-- moves to a column whose check allows it.
ALTER TABLE claim ADD COLUMN status_pending VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status_pending IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'));
UPDATE claim SET status_pending = status;
ALTER TABLE claim DROP COLUMN status;
ALTER TABLE claim ALTER COLUMN status_pending RENAME TO status;
-- A claim due above the sheet's review threshold goes to REVIEW when opened, until a steward's
-- review makes it OPEN. The status's allowed values, on the claim and in its status log, gain
-- REVIEW, so each status moves to a column whose check allows it.
ALTER TABLE claim ADD COLUMN status_review VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status_review IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'DELETED', 'REVIEW'));
UPDATE claim SET status_review = status;
ALTER TABLE claim DROP COLUMN status;
ALTER TABLE claim ALTER COLUMN status_review RENAME TO status;

ALTER TABLE claim_log ADD COLUMN status_review VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status_review IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'DELETED', 'REVIEW'));
UPDATE claim_log SET status_review = status;
ALTER TABLE claim_log DROP COLUMN status;
ALTER TABLE claim_log ALTER COLUMN status_review RENAME TO status;
ALTER TABLE claim_log ALTER COLUMN status DROP DEFAULT;
-- The grades added to a sheet beyond A, B and C, comma separated in alphabetical order; null for none.
-- A grade is a code of one to three capital letters.
ALTER TABLE sheet ADD COLUMN added_grades VARCHAR(4000);
ALTER TABLE sheet ALTER COLUMN retired_grades SET DATA TYPE VARCHAR(4000);
ALTER TABLE sheet ALTER COLUMN default_grade SET DATA TYPE VARCHAR(3);
